namespace BiliLite.Api { public static class ApiHelper { public const string API_BASE_URL="https://api.bilibili.com"; } public class ApiResult { public bool status=true; public string message=""; string json; public ApiResult(string j){json=j;} public Task<T> GetJson<T>()=>Task.FromResult(JsonConvert.DeserializeObject<T>(json)); } public class ApiModel { public RestSharp.Method method; public string baseUrl; public string parameter; public bool need_cookie; public Task<ApiResult> Request(){ AccountApi.Calls.Add(this); return Task.FromResult(new ApiResult(AccountApi.Responses.Dequeue())); } public static List<ApiModel> Calls=new(); public static Queue<string> Responses=new(); } public class AccountApi { public static List<ApiModel> Calls=new(); public static Queue<string> Responses=new(); public static string Deleted; __ACTUAL_HISTORY_WBI__ public ApiModel DelHistory(string id){Deleted=id; return new ApiModel();} } }
namespace BiliLite.Modules.User { internal static class Probe { static void Check(bool b,string n){if(!b)throw new Exception("FAIL: "+n); Console.WriteLine("PASS: "+n);} public static async Task Main(){
var vm=new HistoryVM(); BiliLite.Api.AccountApi.Calls.Clear(); BiliLite.Api.AccountApi.Responses.Clear();
BiliLite.Api.AccountApi.Responses.Enqueue("{\"code\":0,\"data\":{\"cursor\":{\"max\":88,\"view_at\":77},\"list\":[{\"title\":\"Archive\",\"cover\":\"pic\",\"author_name\":\"owner\",\"author_face\":\"face\",\"author_mid\":4,\"view_at\":70,\"kid\":\"archive-kid\",\"history\":{\"oid\":123,\"bvid\":\"BVx\",\"epid\":9,\"cid\":10,\"business\":\"archive\"}},{\"title\":\"PGC\",\"covers\":[\"cover2\"],\"kid\":\"pgc-kid\",\"history\":{\"oid\":222,\"epid\":333,\"business\":\"pgc\"}}]}}");
await vm.LoadHistory(); var first=BiliLite.Api.AccountApi.Calls[0]; Check(first.method==RestSharp.Method.Get && first.baseUrl.EndsWith("/x/web-interface/history/cursor") && first.parameter=="max=0&view_at=0&business=" && first.need_cookie,"initial cookie GET with zero cursor and plain query");
Check(vm.Videos.Count==2 && vm.Videos[0].aid=="BVx" && vm.Videos[0].pic=="pic" && vm.Videos[0].owner.name=="owner" && vm.Videos[0].kid=="archive-kid" && vm.Videos[0].historyOid==123 && vm.Videos[1].cover=="cover2" && vm.Videos[1].historyEpid==333,"DTO mapping, archive/PGC navigation fields and separate nested OID");
BiliLite.Api.AccountApi.Responses.Enqueue("{\"code\":0}"); vm.Del(vm.Videos[0]); Check(BiliLite.Api.AccountApi.Deleted=="archive_archive-kid","deletion retains business plus top-level kid"); BiliLite.Api.AccountApi.Calls.Clear();
BiliLite.Api.AccountApi.Responses.Enqueue("{\"code\":0,\"data\":{\"cursor\":{\"max\":44,\"view_at\":33},\"list\":[{\"title\":\"next\",\"kid\":\"k2\",\"history\":{\"oid\":2,\"business\":\"archive\"}}]}}"); await vm.LoadHistory(); Check(BiliLite.Api.AccountApi.Calls[0].parameter=="max=88&view_at=77&business=" && vm.Videos.Count==2,"cursor request and page append");
BiliLite.Api.AccountApi.Responses.Enqueue("{\"code\":0,\"data\":{\"cursor\":{\"max\":0,\"view_at\":0},\"list\":[]}}"); await vm.LoadHistory(); Check(!vm.ShowLoadMore && vm.Videos.Count==2,"empty terminal page hides load more");
BiliLite.Api.AccountApi.Responses.Enqueue("{\"code\":0,\"data\":{\"cursor\":{\"max\":88,\"view_at\":77},\"list\":[{\"title\":\"Archive\",\"kid\":\"archive-kid\",\"history\":{\"oid\":123,\"bvid\":\"BVx\",\"business\":\"archive\"}}]}}"); vm.Refresh(); await Task.Yield(); Check(BiliLite.Api.AccountApi.Calls.Count==3 && BiliLite.Api.AccountApi.Calls[2].parameter=="max=0&view_at=0&business=" && vm.Videos.Count==1,"refresh resets cursor and collection");
Console.WriteLine("Observed request: GET "+first.baseUrl+"?"+first.parameter+" (cookie enabled)");
} } }
